CREATE TABLE test.sql_server_decimal (
    dec_col DECIMAL (4, 2),
    num_col NUMERIC (4, 2)
);

INSERT INTO test.sql_server_decimal (dec_col, num_col)
VALUES (10.05, 20.05);

INSERT INTO test.sql_server_decimal (dec_col, num_col)
VALUES (99.999, 12.345);

CREATE TABLE #Prices (price DECIMAL(10,2) NOT NULL);

INSERT INTO #Prices (price) VALUES (19.99), (5.05), (0.10);

SELECT
    SUM(price)                             AS total,        -- 25.14
    CAST(SUM(price) / 3 AS DECIMAL(10,2))  AS avg_rounded,   -- 8.38
    ROUND(SUM(price) / 3, 2)               AS rounded;

SELECT CAST(1.0 / 3 AS DECIMAL(10,4))      AS one_third;     -- 0.3333
